// Constant-time comparison to prevent timing attacks
// Returns 0 if equal, non-zero otherwise
static int secure_compare(const uint8_t* a, const uint8_t* b, size_t len) {
    uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result;
}

// HMAC-SHA256 stub (in production, use OpenSSL)
static void hmac_sha256(const uint8_t* key, size_t key_len,
                        const uint8_t* data, size_t data_len,
                        uint8_t* out) {
    // Simplified for demonstration - XOR-based MAC
    // In production this would be real HMAC-SHA256
    uint8_t pad[32] = {0};
    for (size_t i = 0; i < key_len && i < 32; i++) pad[i] = key[i];
    for (size_t i = 0; i < 32; i++) out[i] = pad[i];
    for (size_t i = 0; i < data_len; i++) {
        out[i % 32] ^= data[i];
    }
    // Second pass for avalanche
    for (size_t i = 0; i < 32; i++) {
        out[i] = (out[i] * 251 + 67) ^ out[(i + 17) % 32];
    }
}

struct TokenComponents {
    std::string user_id;
    std::string timestamp;
    std::string permissions;
    std::vector<uint8_t> provided_mac;
    bool valid_structure;
};

class APIGateway {
private:
    uint8_t signing_key_[32];
    std::map<std::string, std::string> user_roles_;
    static constexpr size_t MAC_SIZE = 32;

    static std::string bytes_to_hex(const uint8_t* data, size_t len) {
        std::string result;
        const char* hex = "0123456789abcdef";
        for (size_t i = 0; i < len; i++) {
            result += hex[data[i] >> 4];
            result += hex[data[i] & 0xf];
        }
        return result;
    }

    static std::vector<uint8_t> hex_to_bytes(const std::string& hex) {
        std::vector<uint8_t> result;
        for (size_t i = 0; i + 1 < hex.size(); i += 2) {
            uint8_t hi = 0, lo = 0;
            char c = hex[i];
            if (c >= '0' && c <= '9') hi = c - '0';
            else if (c >= 'a' && c <= 'f') hi = c - 'a' + 10;
            else return {};
            c = hex[i+1];
            if (c >= '0' && c <= '9') lo = c - '0';
            else if (c >= 'a' && c <= 'f') lo = c - 'a' + 10;
            else return {};
            result.push_back((hi << 4) | lo);
        }
        return result;
    }

    TokenComponents parse_token(const std::string& token) {
        TokenComponents tc;
        tc.valid_structure = false;

        // Split by dots
        std::vector<std::string> parts;
        std::istringstream iss(token);
        std::string part;
        while (std::getline(iss, part, '.')) {
            parts.push_back(part);
        }

        if (parts.size() != 4) return tc;

        tc.user_id = parts[0];
        tc.timestamp = parts[1];
        tc.permissions = parts[2];
        tc.provided_mac = hex_to_bytes(parts[3]);

        if (tc.provided_mac.empty()) return tc;
        tc.valid_structure = true;
        return tc;
    }

    // Compute expected MAC for token payload
    std::vector<uint8_t> compute_mac(const std::string& user_id,
                                      const std::string& timestamp,
                                      const std::string& permissions) {
        std::string payload = user_id + "." + timestamp + "." + permissions;
        std::vector<uint8_t> mac(MAC_SIZE);
        hmac_sha256(signing_key_, 32,
                   reinterpret_cast<const uint8_t*>(payload.c_str()),
                   payload.size(), mac.data());
        return mac;
    }

    // Verify token MAC with constant-time comparison
    // SECURITY: Always compare exactly MAC_SIZE bytes - reject tokens with wrong MAC length
    bool verify_token_mac(const TokenComponents& tc) {
        auto expected = compute_mac(tc.user_id, tc.timestamp, tc.permissions);

        // Reject if provided MAC is not exactly the expected length
        if (tc.provided_mac.size() != MAC_SIZE) {
            return false;
        }

        return secure_compare(expected.data(), tc.provided_mac.data(), MAC_SIZE) == 0;
    }

public:
    APIGateway() {
        // Initialize signing key from a cryptographically secure entropy source.
        // Using a fixed PRNG seed would make the key predictable and forgeable.
        std::random_device rd;
        for (int i = 0; i < 32; i++) {
            signing_key_[i] = static_cast<uint8_t>(rd() & 0xFF);
        }
        user_roles_["alice"] = "admin";
        user_roles_["bob"] = "user";
        user_roles_["charlie"] = "user";
    }

    // Generate a valid token for a user
    std::string generate_token(const std::string& user_id, const std::string& permissions) {
        auto now = std::chrono::system_clock::now();
        auto ts = std::to_string(std::chrono::duration_cast<std::chrono::seconds>(
            now.time_since_epoch()).count());

        auto mac = compute_mac(user_id, ts, permissions);
        return user_id + "." + ts + "." + permissions + "." + bytes_to_hex(mac.data(), mac.size());
    }

    // Authenticate and authorize a request
    struct AuthResult {
        bool authenticated;
        bool authorized;
        std::string user_id;
        std::string permissions;
        std::string error;
    };

    AuthResult process_request(const std::string& token, const std::string& required_permission) {
        AuthResult result = {false, false, "", "", ""};

        // Parse token
        auto tc = parse_token(token);
        if (!tc.valid_structure) {
            result.error = "malformed token";
            return result;
        }

        // Verify MAC
        if (!verify_token_mac(tc)) {
            result.error = "invalid signature";
            return result;
        }

        result.authenticated = true;
        result.user_id = tc.user_id;
        result.permissions = tc.permissions;

        // Check authorization
        if (tc.permissions.find(required_permission) != std::string::npos) {
            result.authorized = true;
        } else if (user_roles_.count(tc.user_id) && user_roles_[tc.user_id] == "admin") {
            result.authorized = true; // Admin override
        } else {
            result.error = "insufficient permissions";
        }

        return result;
    }

    // API endpoint: get user data
    std::string handle_get_user_data(const std::string& token, const std::string& target_user) {
        auto auth = process_request(token, "read:" + target_user);
        if (!auth.authenticated) return "{\"error\": \"" + auth.error + "\"}";
        if (!auth.authorized) return "{\"error\": \"" + auth.error + "\"}";
        return "{\"user\": \"" + target_user + "\", \"data\": \"sensitive_info\"}";
    }
};

int main() {
    APIGateway gw;

    // Generate legitimate token for bob with limited permissions
    auto bob_token = gw.generate_token("bob", "read:bob");
    std::cout << "Bob's token: " << bob_token << std::endl;

    // Bob accessing his own data (should succeed)
    auto r1 = gw.handle_get_user_data(bob_token, "bob");
    std::cout << "Bob reads own data: " << r1 << std::endl;

    // Bob accessing alice's data (should fail)
    auto r2 = gw.handle_get_user_data(bob_token, "alice");
    std::cout << "Bob reads alice data: " << r2 << std::endl;

    // Demonstrate that forged tokens with wrong-length MACs are rejected
    std::string forged_base = "bob.9999999999.read:alice";
    for (int attempt = 0; attempt < 256; attempt++) {
        char hex_byte[3];
        snprintf(hex_byte, sizeof(hex_byte), "%02x", attempt);
        std::string forged_token = forged_base + "." + std::string(hex_byte);
        auto result = gw.handle_get_user_data(forged_token, "alice");
        if (result.find("sensitive_info") != std::string::npos) {
            std::cout << "ERROR: Exploit succeeded (should not happen)" << std::endl;
            return 1;
        }
    }
    std::cout << "All 256 single-byte MAC forgery attempts correctly rejected." << std::endl;

    return 0;
}
